export const type = '__type__'
export type TypeOf<C> = C extends Typed<infer T> ? T : unknown
export type Typed<Type, T = object> = {
    [K in keyof (T & { readonly [type]?: Type })]: (T & { readonly [type]?: Type })[K]
}

export const readOnlyOption = [
    'instance_configured',
    'display_read_only',
    'client_script_modifiable',
    'strict_read_only',
] as const

export type readOnlyOptionType = (typeof readOnlyOption)[number]

export type Documentation =
    | {
          hint?: string
          help?: string
          label?: string
          plural?: string
          language?: string
          url?: string
          urlTarget?: string
          /** @deprecated use urlTarget instead */
          url_target?: never
      }
    | {
          hint?: string
          help?: string
          label?: string
          plural?: string
          language?: string
          url?: string
          urlTarget?: never
          /** @deprecated use urlTarget instead */
          url_target?: string
      }

export type Column<Type = unknown, Default extends Type = Type> = Typed<
    Type,
    {
        /** Default value of the field when creating a record */
        default?: Default | string
        /** Maximum length of the field value */
        maxLength?: number | string
        /** Unique label for the column that appears on list headers and form fields */
        label?: string | Documentation[]
        /** Indicates whether the field must contain a value to save a record */
        mandatory?: boolean
        /** Pairs of any supported dictionary attributes (sys_schema_attribute) */
        attributes?: Record<string, string | number | boolean>
        /** Indicates whether to display the field in list and forms */
        active?: boolean
        /** Indicates whether to track the creation, update, and deletion of all records in the table. */
        audit?: boolean
        /** Plural form of the field name */
        plural?: string
        /** Describes field in more verbose form */
        hint?: string
        /** Help information for the field */
        help?: string
        /** Style for the element type such as "radio" */
        widget?: string
        /** Creates another table to store the info that will be captured by this field */
        array?: boolean
        /** Indicates the primary key for a table */
        primary?: boolean
        /** Creates a unique index on this field */
        unique?: boolean
        /** Specifies the read-only behavior for the field */
        readOnlyOption?: readOnlyOptionType
        /** limit the values available to select based on the value of the dependent field */
        dependent?: string
    } & (
        | {
              /** Indicates whether you can edit the field value */
              readOnly?: boolean
              /** Definition of a function that the field performs */
              functionDefinition?: string
              /** Indicates if the value of this field is a reference to another table in the schema */
              tableReference?: boolean
              /** Indicates if the value of this field connotes the "element type" */
              elementReference?: boolean
              /** Enables spell check for this field */
              spellCheck?: boolean
              /** Displays the field value as XML */
              xmlView?: boolean
              /** Enables a natural language search on this field */
              textIndex?: boolean
              /** @deprecated Use readOnly instead */
              read_only?: never
              /** @deprecated Use functionDefinition instead */
              function_definition?: never
              /** @deprecated Use tableReference instead */
              table_reference?: never
              /** @deprecated Use elementReference instead */
              element_reference?: never
              /** @deprecated Use spellCheck instead */
              spell_check?: never
              /** @deprecated Use xmlView instead */
              xml_view?: never
              /** @deprecated Use textIndex instead */
              text_index?: never
          }
        | {
              /** @deprecated Use readOnly instead */
              read_only?: boolean
              /** @deprecated Use functionDefinition instead */
              function_definition?: string
              /** @deprecated Use tableReference instead */
              table_reference?: boolean
              /** @deprecated Use elementReference instead */
              element_reference?: boolean
              /** @deprecated Use spellCheck instead */
              spell_check?: boolean
              /** @deprecated Use xmlView instead */
              xml_view?: boolean
              /** @deprecated Use textIndex instead */
              text_index?: boolean
              /** Indicates whether you can edit the field value */
              readOnly?: never
              /** Definition of a function that the field performs */
              functionDefinition?: never
              /** Indicates if the value of this field is a reference to another table in the schema */
              tableReference?: never
              /** Indicates if the value of this field connotes the "element type" */
              elementReference?: never
              /** Enables spell check for this field */
              spellCheck?: never
              /** Displays the field value as XML */
              xmlView?: never
              /** Enables a natural language search on this field */
              textIndex?: never
          }
    )
>

/**
 * Create a column in a table (`sys_dictionary`)
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param properties - an object containing the following properties:
 *   * **active**? - indicates whether to display the field in list and forms
 *   * **attributes**? - pairs of any supported dictionary attributes (`sys_schema_attribute`)
 *   * **audit**?
 *   * **default**? - default value of the field when creating a record
 *   * **functionDefinition**? - definition of a function that the field performs
 *   * **label**? - unique label for the column that appears on list headers and form fields
 *   * **mandatory**? - indicates whether the field must contain a value to save a record
 *   * **readOnly**? - indicates whether you can edit the field value
 *   * **plural**? - plural for field
 *   * **hint**? - describes field in more verbose form
 *   * **help**? - help information for the field
 *   * **widget**? - style for the element type such as "radio"
 *   * **tableReference**? -  value of this field is a reference to another table in the schema
 *   * **elementReference**? - value of this field connotes the "element type"
 *   * **unique**? - system creates index on this field on install
 *   * **spellCheck**? - display spell check icon
 *   * **xmlView**? - show text as xml
 *   * **array**? -Creates another table to store the info that will be captured by this field
 *   * **textIndex**? - Enables a natural language search on this field.
 *   * **primary**? - Indicates the primary key for a table
 */
export function Column<const Type, const Default extends Type, const P extends Column<Type, Default>>(
    properties: P & Column<Type, Default>
) {
    return properties as Typed<Type, P>
}
